#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Wizard for issue #704: EAS projects, the Expo token and the store identifiers
# the mobile app needs before its first build. Run from the repository root:
#   bash scripts/setup/issue-704.sh
# Details: docs/ops/mobile.md, « Mise en place, une fois ».

REPO_ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
MOBILE_DIR="$REPO_ROOT/apps/mobile"
TOTAL_STAGES=5

# set_json_key FILE DOTTED.PATH VALUE sets one string key in a JSON file, keeping its formatting.
set_json_key() {
  node -e '
    const fs = require("fs");
    const [file, dotted, value] = process.argv.slice(1);
    const data = JSON.parse(fs.readFileSync(file, "utf8"));
    const keys = dotted.split(".");
    let node = data;
    for (const k of keys.slice(0, -1)) { node[k] = node[k] || {}; node = node[k]; }
    node[keys[keys.length - 1]] = value;
    fs.writeFileSync(file, JSON.stringify(data, null, 2) + "\n");
  ' "$1" "$2" "$3"
}

banner "Jobbbox app: EAS and the stores"

# ── Stage 1: EAS project ──────────────────────────────────────────────────
stage "EAS project"
say "The app needs one EAS project, which holds its builds and EAS Update channels."
step "In a terminal, from the repository, run:  cd apps/mobile && npx eas-cli init"
step "Log in with the organisation's Expo account and accept the project creation."
step "Copy the project ID it prints (a UUID, shown on expo.dev under the project settings)."
pause "Press Enter once 'eas init' has finished."
ask EAS_PROJECT_ID "Paste the EAS project ID:"
if [[ -n "$EAS_PROJECT_ID" ]]; then
  set_json_key "$MOBILE_DIR/app.json" "expo.extra.eas.projectId" "$EAS_PROJECT_ID"
  printf '  %s✓ wrote%s expo.extra.eas.projectId → apps/mobile/app.json\n' "$GREEN" "$RESET"
  WRITTEN_ENV+=("expo.extra.eas.projectId")
else
  warn "no project ID given; set expo.extra.eas.projectId in apps/mobile/app.json later"
  SKIPPED+=("expo.extra.eas.projectId in apps/mobile/app.json")
fi

# ── Stage 2: Expo access token as a repo secret ───────────────────────────
stage "Expo access token (EXPO_TOKEN)"
say "CI (mobile.yml) builds and updates the app with this token."
open_url "https://expo.dev/settings/access-tokens"
step "Create a new access token for the organisation's account (name it 'jobhub-ci')."
step "Copy the token: it is shown only once."
ask_secret EXPO_TOKEN "Paste the Expo access token (hidden):"
if [[ -n "$EXPO_TOKEN" ]]; then
  set_secret EXPO_TOKEN "$EXPO_TOKEN"
else
  warn "no token given; run 'gh secret set EXPO_TOKEN' later"
  SKIPPED+=("GitHub secret EXPO_TOKEN (gh secret set EXPO_TOKEN)")
fi

# ── Stage 3: store credentials, kept by EAS ───────────────────────────────
stage "Store credentials, kept by EAS"
say "EAS keeps the App Store Connect key and the Google Play service account. Nothing goes in the repo."
step "In a terminal, from apps/mobile, run:  npx eas-cli credentials"
step "iOS: add the App Store Connect API key (signing and TestFlight upload)."
step "Android: add the Google Play service account key (internal track upload)."
pause "Press Enter once both credentials are saved in EAS."
confirm "Were both credentials saved?" || warn "not confirmed; finish 'eas credentials' before the first build"

# ── Stage 4: App Store Connect app identifier ─────────────────────────────
stage "App Store Connect app"
say "Create the app 'ai.jobbbox.app' in App Store Connect, then note its numeric Apple ID."
open_url "https://appstoreconnect.apple.com/apps"
step "Open the app, then copy the Apple ID shown under 'General > App Information' (digits only)."
ask APPLE_APP_ID "Paste the Apple ID (digits):"
if [[ -n "$APPLE_APP_ID" ]]; then
  set_json_key "$MOBILE_DIR/app.json" "expo.extra.appStoreId" "$APPLE_APP_ID"
  set_json_key "$MOBILE_DIR/eas.json" "submit.staging.ios.ascAppId" "$APPLE_APP_ID"
  set_json_key "$MOBILE_DIR/eas.json" "submit.production.ios.ascAppId" "$APPLE_APP_ID"
  printf '  %s✓ wrote%s the Apple ID to app.json and eas.json (staging, production)\n' "$GREEN" "$RESET"
  WRITTEN_ENV+=("expo.extra.appStoreId")
else
  warn "no Apple ID given; set appStoreId in app.json and ascAppId in eas.json later"
  SKIPPED+=("appStoreId in apps/mobile/app.json and ascAppId in apps/mobile/eas.json")
fi

# ── Stage 5: Google Play first upload, by hand ────────────────────────────
stage "Google Play listing"
say "Google requires the very first upload of an app to be made by hand. EAS Submit handles the later ones."
open_url "https://play.google.com/console"
step "Create the app 'ai.jobbbox.app' in the Play Console."
step "Upload a first build by hand to the internal testing track, then return here."
pause "Press Enter once the first Play upload is done."
confirm "Is the app listed in the Play Console?" || warn "not confirmed; create the Play listing before the first Android submit"

finish
